package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void runGeneratesCompleteBuilderSourceWithoutDuplicateDeclarations() throws IOException {
    Path generatedFile = temporaryDirectory.resolve(
        "org/apache/parquet/filter2/recordlevel/IncrementallyUpdatedFilterPredicateBuilder.java");
    Files.createDirectories(generatedFile.getParent());

    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(generatedFile.toFile());

    generator.run();

    String source = Files.readString(generatedFile, StandardCharsets.UTF_8);

    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.contains(
        "public class IncrementallyUpdatedFilterPredicateBuilder "
            + "extends IncrementallyUpdatedFilterPredicateBuilderBase"));
    assertTrue(source.contains("visit(Eq<T> pred)"));
    assertTrue(source.contains("visit(NotEq<T> pred)"));
    assertTrue(source.contains("visit(In<T> pred)"));
    assertTrue(source.contains("visit(NotIn<T> pred)"));
    assertTrue(source.contains("visit(Lt<T> pred)"));
    assertTrue(source.contains("visit(LtEq<T> pred)"));
    assertTrue(source.contains("visit(Gt<T> pred)"));
    assertTrue(source.contains("visit(GtEq<T> pred)"));
    assertTrue(source.contains("visit(UserDefined<T, U> pred)"));
    assertTrue(source.contains("visit(LogicalNotUserDefined<T, U> notPred)"));

    Pattern duplicateTargetDeclaration = Pattern.compile(
        "(?s).*final (int|long|float|double|Binary) target = .*?;\\s+"
            + "\\1 target = .*?;.*");
    assertFalse(
        duplicateTargetDeclaration.matcher(source).matches(),
        "Generated inequality methods must contain one target declaration per branch");
  }
}

package org.apache.parquet.filter2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Tests for IncrementallyUpdatedFilterPredicateGenerator.run()
 * Verifies that the generator writes a Java class IncrementallyUpdatedFilterPredicateGeneratorRunTests the expected structure.
 */
public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  public void generatedCodeContainsExpectedStructure() throws IOException {
    // Arrange: create a fresh temporary directory and output file
    Path dir = Files.createTempDirectory("parquet-gen-test");
    File outFile = new File(dir.toFile(), "IncrementallyUpdatedFilterPredicateBuilder.java");

    // Act: run the generator to produce the code
    IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(outFile);
    generator.run();

    // Read the generated content
    String content = Files.readString(outFile.toPath(), StandardCharsets.UTF_8);

    // Assert: verify key structural aspects derived from the specification
    assertNotNull(content, "Generated content should not be null");
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"),
        "Generated content should declare the class IncrementallyUpdatedFilterPredicateBuilder extending the base.");
    assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"),
        "Generated content should include a public constructor with List<PrimitiveColumnIO> leaves.");
    assertTrue(content.contains("public <T extends Comparable<T>, U extends UserDefinedPredicate<T>> IncrementallyUpdatedFilterPredicate visit(UserDefined<T, U> pred)"),
        "Generated content should include the UserDefined visit method with the correct signature.");
    assertTrue(content.contains("class IncrementallyUpdatedFilterPredicateBuilder"),
        "Generated content should contain the class declaration for IncrementallyUpdatedFilterPredicateBuilder.");

    // Cleanup
    try {
      if (outFile.exists()) {
        outFile.delete();
      }
      Files.deleteIfExists(dir);
    } catch (IOException ignored) {
      // ignore cleanup errors
    }
  }
}

