package org.apache.parquet.format.converter;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import org.apache.parquet.format.ColumnChunk;
import org.apache.parquet.format.ColumnMetaData;
import org.apache.parquet.format.CompressionCodec;
import org.apache.parquet.format.Encoding;
import org.apache.parquet.format.FileMetaData;
import org.apache.parquet.format.RowGroup;
import org.apache.parquet.format.SchemaElement;
import org.apache.parquet.format.Type;
import org.apache.parquet.hadoop.metadata.BlockMetaData;
import org.apache.parquet.hadoop.metadata.ColumnChunkMetaData;
import org.apache.parquet.hadoop.metadata.ColumnPath;
import org.apache.parquet.hadoop.metadata.ParquetMetadata;
import org.apache.parquet.io.ParquetDecodingException;
import org.junit.jupiter.api.Test;

class ParquetMetadataConverterFromParquetMetadataTests {

  @Test
  void convertsRowGroupAndColumnMetadataIncludingRowIndexOffset() throws Exception {
    FileMetaData input = fileMetadata(singleRowGroup("data.parquet", 17L, 91L, 12L));
    RowGroup rowGroup = input.getRow_groups().get(0);

    Map<RowGroup, Long> rowIndexOffsets = new HashMap<>();
    rowIndexOffsets.put(rowGroup, 1234L);

    ParquetMetadata result =
        new ParquetMetadataConverter()
            .fromParquetMetadata(input, null, false, rowIndexOffsets);

    assertEquals(1, result.getBlocks().size());

    BlockMetaData block = result.getBlocks().get(0);
    assertEquals(17L, block.getRowCount());
    assertEquals(91L, block.getTotalByteSize());
    assertEquals(1234L, block.getRowIndexOffset());
    assertEquals(12, block.getOrdinal());
    assertEquals("data.parquet", block.getPath());
    assertEquals(1, block.getColumns().size());

    ColumnChunkMetaData column = block.getColumns().get(0);
    assertEquals(ColumnPath.get("id"), column.getPath());
    assertEquals(17L, column.getValueCount());
    assertEquals("writer", result.getFileMetaData().getCreatedBy());
  }

  @Test
  void rejectsColumnChunksStoredInDifferentFiles() {
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(1L);
    rowGroup.setTotal_byte_size(2L);
    rowGroup.setOrdinal((short) 0);
    rowGroup.setColumns(Arrays.asList(
        columnChunk("first.parquet", 0L),
        columnChunk("second.parquet", 100L)));

    FileMetaData input = fileMetadata(rowGroup);

    assertThrows(
        ParquetDecodingException.class,
        () -> new ParquetMetadataConverter().fromParquetMetadata(
            input, null, false, Collections.emptyMap()));
  }

  private static FileMetaData fileMetadata(RowGroup rowGroup) {
    FileMetaData metadata = new FileMetaData();
    metadata.setSchema(Arrays.asList(
        schemaElement("schema", null, 1),
        schemaElement("id", Type.INT32, null)));
    metadata.setCreated_by("writer");
    metadata.setRow_groups(Collections.singletonList(rowGroup));
    return metadata;
  }

  private static RowGroup singleRowGroup(
      String filePath, long rowCount, long totalByteSize, long dataPageOffset) {
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(rowCount);
    rowGroup.setTotal_byte_size(totalByteSize);
    rowGroup.setOrdinal((short) 12);
    rowGroup.setColumns(Collections.singletonList(columnChunk(filePath, dataPageOffset)));
    return rowGroup;
  }

  private static ColumnChunk columnChunk(String filePath, long dataPageOffset) {
    ColumnMetaData metadata = new ColumnMetaData();
    metadata.setType(Type.INT32);
    metadata.setEncodings(Collections.singletonList(Encoding.PLAIN));
    metadata.setPath_in_schema(Collections.singletonList("id"));
    metadata.setCodec(CompressionCodec.UNCOMPRESSED);
    metadata.setNum_values(17L);
    metadata.setTotal_uncompressed_size(68L);
    metadata.setTotal_compressed_size(68L);
    metadata.setData_page_offset(dataPageOffset);

    ColumnChunk chunk = new ColumnChunk();
    chunk.setFile_path(filePath);
    chunk.setMeta_data(metadata);
    return chunk;
  }

  private static SchemaElement schemaElement(String name, Type type, Integer childCount) {
    SchemaElement element = new SchemaElement(name);
    if (type != null) {
      element.setType(type);
      element.setRepetition_type(org.apache.parquet.format.FieldRepetitionType.REQUIRED);
    }
    if (childCount != null) {
      element.setNum_children(childCount.shortValue());
    }
    return element;
  }
}

package org.apache.parquet.format.converter;

import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.HashMap;

import org.apache.parquet.format.FileMetaData;
import org.apache.parquet.hadoop.metadata.ParquetMetadata;
import org.junit.jupiter.api.Test;

/**
 * ParquetMetadataConverterFromParquetMetadataTests
 * 
 * This test suite exercises the ParquetMetadataConverter.fromParquetMetadata method.
 * The production code expects non-null inputs and a valid Parquet thrift FileMetaData.
 * This test focuses on ensuring that clearly invalid input (null FileMetaData)
 * results in a predictable exception, helping to validate the method's input validation
 * contract and to distinguish correct behavior from potential null-pointer pitfalls
 * in the implementation.
 */
public class ParquetMetadataConverterFromParquetMetadataTests {

  @Test
  public void testFromParquetMetadataThrowsOnNullParquetMetadata() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    // The preconditions specify parquetMetadata must not be null.
    // Ensure that passing null yields a clear failure (NPE) from the method.
    assertThrows(NullPointerException.class, () -> {
      converter.fromParquetMetadata(null, null, false, new HashMap<>());
    });
  }
}
